ed_count'].'</strong></div><div><span>Duplicates</span><strong>'.$r['duplicate_count'].'</strong></div><div><span>Errors</span><strong>'.$r['error_count'].'</strong></div></div><div class="card table-wrap"><div class="card-head"><div><h3>Error Validation Report</h3><span class="muted small">Use this templated view to correct the source data before retrying.</span></div></div><table class="table"><tr><th>#</th><th>Error Type</th><th>Details</th><th>Required Action</th></tr>';if(!$errors)echo '<tr><td colspan="4" class="empty-state">No errors recorded for this import.</td></tr>';foreach($errors as $i=>$er){$txt=is_array($er)?json_encode($er,JSON_UNESCAPED_UNICODE):(string)$er;$type=str_contains(strtolower($txt),'unmapped')?'Unmapped Item':(str_contains(strtolower($txt),'quantity')?'Invalid Quantity':(str_contains(strtolower($txt),'duplicate')?'Duplicate':'Validation Error'));$action=$type==='Unmapped Item'?'Map the product before retrying.':($type==='Invalid Quantity'?'Correct the quantity in the source file.':($type==='Duplicate'?'No action if already processed.':'Review and correct the source row.'));echo '<tr><td>'.($i+1).'</td><td>'.badge($type,'danger').'</td><td>'.e($txt).'</td><td>'.e($action).'</td></tr>';}echo '</table></div>';}
